	/**
	 * Add shared inline styles to a WordPress style handle once per request.
	 *
	 * @param string $handle Style handle.
	 * @return void
	 */
	public static function add_inline_styles_to_handle( string $handle ): void {
		if ( isset( self::$inline_styles_added[ $handle ] ) ) {
			return;
		}

		wp_add_inline_style( $handle, self::get_inline_styles() );

		self::$inline_styles_added[ $handle ] = true;
	}

	/**
	 * Constructor.
	 *
	 * @return void
	 */
	protected function __construct() {
		EditorAssetManager::get_instance();
		FrontendAssetManager::get_instance();
	}
